import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";

const branch = execSync("git branch --show-current", { encoding: "utf8" }).trim();
if (branch !== "vNext") throw new Error(`Expected vNext branch, got ${branch}`);

const status = execSync("git status --porcelain", { encoding: "utf8" }).trim();
if (status) throw new Error("Working tree must be clean before applying Auth + Onboarding Foundation 01.");

const payload = JSON.parse(Buffer.from("", "base64").toString("utf8"));
for (const [rel, content] of Object.entries(payload)) {
  fs.mkdirSync(path.dirname(rel), { recursive: true });
  fs.writeFileSync(rel, content, "utf8");
}

const cssPath = "src/app/globals.css";
const marker = "/* Auth + Guided Onboarding Foundation 01 */";
let css = fs.readFileSync(cssPath, "utf8");
if (!css.includes(marker)) {
  css += "\n/* Auth + Guided Onboarding Foundation 01 */\n.authCard,\n.onboardingWide {\n  width: min(100%, 720px);\n  margin: 0 auto;\n  border: 1px solid var(--border);\n  border-radius: 24px;\n  background: var(--surface);\n  padding: clamp(24px, 4vw, 44px);\n  box-shadow: 0 20px 60px rgba(15, 23, 42, 0.08);\n}\n.onboardingWide { width: min(100%, 1080px); }\n.muted { color: var(--muted); }\n.formStack { display: grid; gap: 16px; margin-top: 24px; }\n.formStack label { display: grid; gap: 8px; font-weight: 650; }\n.formStack input {\n  width: 100%;\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 12px 14px;\n  background: var(--surface);\n  color: var(--text);\n  font: inherit;\n}\n.formGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n.formDivider { display: flex; align-items: center; gap: 12px; margin: 24px 0; color: var(--muted); }\n.formDivider::before, .formDivider::after { content: \"\"; height: 1px; flex: 1; background: var(--border); }\n.formNotice { border-radius: 12px; padding: 12px 14px; margin-top: 18px; }\n.errorNotice { background: #fff1f2; border: 1px solid #fecdd3; color: #9f1239; }\n.successNotice { background: #f0fdf4; border: 1px solid #bbf7d0; color: #166534; }\n.formFooter { margin-top: 22px; color: var(--muted); }\n.secondaryButton { background: transparent; color: var(--text); border: 1px solid var(--border); }\n.secondaryButton:disabled { opacity: .55; cursor: not-allowed; }\n.stepRow { display: inline-flex; align-items: center; gap: 10px; margin-bottom: 18px; color: var(--muted); }\n.stepRow strong { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 999px; background: var(--text); color: var(--surface); }\n.planGrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-top: 28px; }\n.planCard, .metricCard, .workspacePanel, .demoStep, .demoBanner {\n  border: 1px solid var(--border);\n  border-radius: 18px;\n  padding: 22px;\n  background: var(--surface);\n}\n.featuredPlan { box-shadow: 0 12px 36px rgba(15, 23, 42, .08); }\n.planCard ul { padding-left: 20px; color: var(--muted); min-height: 90px; }\n.demoSteps { display: grid; gap: 14px; margin: 28px 0; }\n.demoStep { display: flex; gap: 16px; align-items: flex-start; }\n.demoStep > strong { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 999px; background: var(--text); color: var(--surface); flex: 0 0 auto; }\n.demoStep h2 { margin: 0 0 4px; font-size: 1.05rem; }\n.demoStep p { margin: 0; color: var(--muted); }\n.demoBanner { display: grid; gap: 6px; margin-bottom: 24px; background: var(--soft); }\n.workspacePage { min-height: 100vh; padding: clamp(24px, 5vw, 72px); background: var(--background); }\n.workspaceHeader { display: flex; justify-content: space-between; gap: 24px; align-items: flex-start; max-width: 1180px; margin: 0 auto 28px; }\n.workspaceHeader h1 { margin-bottom: 4px; }\n.workspaceHeader p { color: var(--muted); }\n.workspaceGrid { max-width: 1180px; margin: 0 auto; display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }\n.metricCard span { display: block; color: var(--muted); font-size: .85rem; margin-bottom: 8px; }\n.metricCard strong { display: block; font-size: 1.35rem; }\n.metricCard p { color: var(--muted); margin-bottom: 0; }\n.workspacePanel { max-width: 1180px; margin: 18px auto 0; }\n@media (max-width: 760px) {\n  .formGrid, .planGrid, .workspaceGrid { grid-template-columns: 1fr; }\n  .workspaceHeader { flex-direction: column; }\n}\n";
  fs.writeFileSync(cssPath, css, "utf8");
}

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
pkg.scripts["db:onboarding:apply"] = "node scripts/db-apply-auth-onboarding-03.mjs";
fs.writeFileSync("package.json", JSON.stringify(pkg, null, 2) + "\n", "utf8");

for (const file of [
  "scripts/db-apply-auth-onboarding-03.mjs"
]) {
  execSync(`node --check ${file}`, { stdio: "inherit" });
}

console.log("Authentication + Guided Onboarding Foundation 01 files applied.");
console.log("Next: npm run db:onboarding:apply");
